// Input per line: 15 adjacency masks, then all eligible four-row sides (from four_rows). Counts of search presentations; repeated presentations harmless. Fix column order of cross graph, permute opposite rows exhaustively.
use std::{io::{self,BufRead},collections::{HashMap,HashSet}};
fn independent(g:&[u32],mut p:u32,k:u32)->bool{if k==0{return true}while p.count_ones()>=k{let i=p.trailing_zeros()as usize;p&=p-1;if independent(g,p&!g[i],k-1){return true}}false}
fn pack(s:u32)->u64{let mut r=0;for i in 0..15{r|=(((s>>i)&1)as u64)<<(4*i)}r}
fn perms()->Vec<[usize;4]>{let mut p=vec![];for i in 0..4{for j in 0..4{for k in 0..4{if i!=j&&j!=k&&i!=k{p.push([i,j,k,6-i-j-k])}}}}p}
type Row=[u32;4]; fn sizes(t:&Row)->Row{t.map(u32::count_ones)} fn side(t:&Row,l:&Row)->bool{(0..4).all(|i|(0..i).all(|j|(t[i]&t[j]).count_ones()+(l[i]&l[j]).count_ones()<=2))}
fn main(){let e:u32=std::env::args().nth(1).unwrap().parse().unwrap();let ps=perms();let mut templates:HashMap<Row,Vec<(Row,Row)>>=HashMap::new();for m in 0u32..65536{if m.count_ones()!=e-21{continue}let l:Row=std::array::from_fn(|i|(m>>(4*i))&15);let r:Row=std::array::from_fn(|i|(0..4).map(|j|((l[j]>>i)&1)<<j).sum());if !r.windows(2).all(|z|z[0]<=z[1])||r.iter().chain(&l).any(|v|!(1..=3).contains(&v.count_ones()))||!ps.iter().any(|p|(0..4).all(|i|l[i]>>p[i]&1!=0)){continue}templates.entry(l.map(|v|6-v.count_ones())).or_default().push((l,r))}
for line in io::stdin().lock().lines(){let v:Vec<u32>=line.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();let a=&v[..15];let mut stats=[0u64;6];let mut sets=vec![0u32];for(i,&v)in a.iter().enumerate(){for j in 0..sets.len(){if sets[j]&v==0{sets.push(sets[j]|1<<i)}}}let f:Vec<_>=sets.into_iter().filter(|x|x.count_ones()==5).collect();let mut fp=HashMap::<u64,Vec<(u32,u32)>>::new();for(i,&x)in f.iter().enumerate(){for &y in &f[i..]{if (x&y).count_ones()<=1{fp.entry(pack(x)+pack(y)).or_default().push((x,y))}}}
let ss:Vec<Row>=v[15..].chunks_exact(4).map(|s|Row::try_from(s).unwrap()).filter(|s|(0..15).all(|i|(0..i).all(|j|(a[i]&a[j]).count_ones()+s.iter().map(|t|(t>>i)&(t>>j)&1).sum::<u32>()<=3))).collect();let mut opp=HashMap::<Row,HashSet<Row>>::new();for s in &ss{for p in &ps{let t=p.map(|i|s[i]);opp.entry(sizes(&t)).or_default().insert(t);}}
let mut cache=HashMap::<Row,Vec<Row>>::new();for t in &ss{if let Some(mats)=templates.get(&sizes(t)){for(l,r)in mats{if !side(t,l){continue}stats[0]+=1;{let qs=cache.entry(*r).or_insert_with(||opp.get(&r.map(|x|6-x.count_ones())).into_iter().flatten().filter(|q|side(q,r)).copied().collect());stats[1]+=qs.len() as u64;let forbidden:Row=std::array::from_fn(|j|(0..4).filter(|&i|l[i]>>j&1!=0).fold(0,|x,i|x|t[i]));for q in qs.iter(){if (q[0]&forbidden[0])|(q[1]&forbidden[1])|(q[2]&forbidden[2])|(q[3]&forbidden[3])!=0{continue}stats[2]+=1;let mut need=0u64;let mut good=true;for i in 0..15{let d=a[i].count_ones()+t.iter().chain(q).map(|s|(s>>i)&1).sum::<u32>();if !(4..=7).contains(&d){good=false;break}need|=((7-d)as u64)<<(4*i)}if !good{continue}for &z in &f{let pz=pack(z);if pz>need{continue}if let Some(pairs)=fp.get(&(need-pz)){for &(x,y)in pairs{if y>z||(x&z).count_ones()>1||(y&z).count_ones()>1{continue}stats[3]+=1;let mut g=[0u32;28];g[..15].copy_from_slice(a);for(i,&s)in t.iter().chain(q).chain([x,y,z].iter()).enumerate(){let h=15+i;g[h]=s;for j in 0..15{if s>>j&1!=0{g[j]|=1<<h}}for j in 0..2{if i>=8||i/4==j{g[h]|=1<<(26+j);g[26+j]|=1<<h}}}for i in 0..4{g[15+i]|=l[i]<<19;g[19+i]|=r[i]<<15}assert!(g.iter().all(|v|v.count_ones()==7));if (0..28).any(|i|(0..i).any(|j|(g[i]&g[j]).count_ones()>3)){continue}stats[4]+=1;if !independent(&g,(1<<28)-1,8){stats[5]+=1}}}}}}}}}println!("{}",stats.map(|v|v.to_string()).join(" "));}}
